codeExamples.code:
-- PROVIDER side: expose only a governed slice via a secure view (no raw PII)
CREATE OR REPLACE SECURE VIEW analytics.public.sales_by_region AS
SELECT region,
       sale_date,
       SUM(amount) AS total_sales      -- aggregated; no customer_id / PII exposed
FROM   analytics.raw.sales
GROUP  BY region, sale_date;

-- Create a share and add the schema + secure view to it
CREATE SHARE sales_share;
GRANT USAGE   ON DATABASE analytics                TO SHARE sales_share;
GRANT USAGE   ON SCHEMA   analytics.public         TO SHARE sales_share;
GRANT SELECT  ON VIEW     analytics.public.sales_by_region TO SHARE sales_share;

-- Grant the share to a specific consumer account (identified by its account locator)
ALTER SHARE sales_share ADD ACCOUNTS = CONSUMER_ACCT_XY12345;

-- CONSUMER side: mount the share as a read-only database and query live data
CREATE DATABASE shared_sales FROM SHARE PROVIDER_ACCT.sales_share;
SELECT region, SUM(total_sales) AS ytd_sales
FROM   shared_sales.public.sales_by_region
WHERE  sale_date >= '2026-01-01'
GROUP  BY region;

-- Revoke instantly when the relationship ends
ALTER SHARE sales_share REMOVE ACCOUNTS = CONSUMER_ACCT_XY12345;

-- PRODUCER cluster: create a datashare and add objects
CREATE DATASHARE sales_share;
ALTER DATASHARE sales_share ADD SCHEMA analytics;
ALTER DATASHARE sales_share ADD TABLE analytics.sales_by_region;   -- ideally a view

-- Grant to a consumer namespace (same account) ...
GRANT USAGE ON DATASHARE sales_share TO NAMESPACE '<consumer-namespace-guid>';
-- ... or to another AWS account (cross-account sharing)
GRANT USAGE ON DATASHARE sales_share TO ACCOUNT '123456789012';

-- CONSUMER cluster: create a local database from the shared datashare
CREATE DATABASE shared_sales_db FROM DATASHARE sales_share
  OF NAMESPACE '<producer-namespace-guid>';

-- Query the shared data live, on the consumer's own compute
SELECT region, SUM(total_sales) AS ytd
FROM   shared_sales_db.analytics.sales_by_region
GROUP  BY region;

-- Inspect what a datashare exposes
SHOW DATASHARES;
SELECT * FROM svv_datashare_objects WHERE share_name = 'sales_share';
